// Parse enhanced callback structure with flow context
const rawData = $json.callback_query?.data || '';

let cbData;
try {
  // Try JSON parse first (new format)
  cbData = JSON.parse(rawData);
} catch (e) {
  // Fallback to legacy format parsing
  if (rawData.includes(':')) {
    const [type, value] = rawData.split(':');
    cbData = { type, value };
  } else {
    cbData = { type: 'unknown', value: rawData };
  }
}

// Extract callback context
return [{
  json: {
    ...$json,
    cb_type: cbData.type || 'unknown',
    cb_chat_id: cbData.chat_id || null,
    cb_flow_instance_id: cbData.flow_instance_id || null,
    cb_pref_id: cbData.pref_id || null,
    cb_value: cbData.value || null,
    cb_timestamp: cbData.timestamp || null,
    cb_message_id: cbData.message_id || null,
    cb_raw: rawData
  }
}];

