// Generate unique flow_instance_id for this conversation
const chatId = $json.chat_id || '';
const timestamp = Date.now();
const random = Math.random().toString(36).substring(2, 8);
const flow_instance_id = `${chatId}_${timestamp}_${random}`;

return [{
  json: {
    ...$json,
    flow_instance_id,
    flow_start_time: timestamp
  }
}];

// CRITICAL SECURITY: Multi-layer callback validation
const cbData = $json;
const actualChatId = $json.callback_query?.message?.chat?.id?.toString() || '';

// Skip validation for legacy callbacks (backward compatibility)
if (!cbData.cb_flow_instance_id) {
  return [{ json: { valid: true, legacy: true, ...cbData } }];
}

// 1. Ownership check
if (cbData.cb_chat_id && cbData.cb_chat_id !== actualChatId) {
  throw new Error("⚠️ This button doesn't belong to your conversation");
}

// 2. Freshness check (30 min)
if (cbData.cb_timestamp) {
  const age = Date.now() - cbData.cb_timestamp;
  if (age > 30 * 60 * 1000) {
    throw new Error("⏱️ Menu expired (30min). Use /post to restart");
  }
}

// All checks passed
return [{ json: { valid: true, ...cbData } }];

